    public static void verify(int stage,java.util.Map<?,?> loaded)throws Exception {
        var field=MapRenderer.class.getDeclaredField("displayed");field.setAccessible(true);
        var displayed=(java.util.List<?>)field.get(MapRenderer.INSTANCE);var report=new JsonArray();var colliders=new JsonArray();var checked=new java.util.HashSet<Integer>();
        for(var p:PROBES){
            if((int)p[0]!=stage)continue;
            double x=p[2],y=p[3],z=p[4],nx=p[5],nz=p[6];float distance=1000;int hit=-1,partHit=-1;
            for(var value:loaded.values()){
                var tile=(MapTile)value;var d=tile.data;if(!displayed.contains(d.id))continue;
                for(int pi=0;pi<d.parts.length;pi++){var v=d.parts[pi].vertices;
                    for(int o=0;o<v.length;o+=15){
                        float t=org.joml.Intersectionf.intersectRayTriangle((float)(x+nx*2-d.anchorX),(float)(y-d.anchorY),(float)(z+nz*2-d.anchorZ),(float)-nx,0,(float)-nz,v[o],v[o+1],v[o+2],v[o+5],v[o+6],v[o+7],v[o+10],v[o+11],v[o+12],1e-6f);
                        if(t>0&&t<distance){distance=t;hit=d.id;partHit=pi;}
                    }
                }
            }
            if(hit!=(int)p[1]||(partHit!=(int)p[7]&&partHit!=2)||distance<1.25||distance>2.05)throw new AssertionError("MLZ stage "+stage+" control at "+x+","+y+","+z+" obstructed/missing: "+hit+"/"+partHit+" distance "+distance);
            if(checked.add(hit)){
                var mc=net.minecraft.client.Minecraft.getInstance();var from=new net.minecraft.world.phys.Vec3(x+nx*2,y,z+nz*2);var to=new net.minecraft.world.phys.Vec3(x-nx*2,y,z-nz*2);
                var block=mc.level.clip(new net.minecraft.world.level.ClipContext(from,to,net.minecraft.world.level.ClipContext.Block.COLLIDER,net.minecraft.world.level.ClipContext.Fluid.NONE,mc.player));
                if(block.getType()!=net.minecraft.world.phys.HitResult.Type.BLOCK||!dev.realworldmc.EarthBlocks.isMapBlock(mc.level.getBlockState(block.getBlockPos())))throw new AssertionError("MLZ wall has no native collision at "+x+","+y+","+z);
                var collider=new JsonObject();collider.addProperty("tile",hit);collider.addProperty("blockPosition",block.getBlockPos().toShortString());collider.addProperty("distanceFromOutside",from.distanceTo(block.getLocation()));colliders.add(collider);
            }
            var row=new JsonObject();row.addProperty("tile",hit);row.addProperty("part",partHit);row.addProperty("distance",distance);row.addProperty("x",x);row.addProperty("y",y);row.addProperty("z",z);report.add(row);
        }
        if(report.isEmpty())throw new AssertionError("No MLZ controls for stage "+stage);
        var result=new JsonObject();result.addProperty("status","PASS: individual MLZ openings visible on displayed reconstruction without overlapping source facades");result.addProperty("rendererJar",Path.of(MapRenderer.class.getProtectionDomain().getCodeSource().getLocation().toURI()).getFileName().toString());result.add("probes",report);result.add("nativeWallColliders",colliders);
        Files.writeString(Path.of("campus-mlz-"+stage+"-result.json"),new GsonBuilder().setPrettyPrinting().create().toJson(result));
    }
